func PnHas(bms *port.BitmapSet, id int32) int32 {
	// 1 when the set holds a bitmap with pixels under `id` (a 0 x 0 stand-in is what a transcript with no bitmap answers).
	if port.BmsHas(bms, id) == 0 {
		return 0
	}
	if port.BitmapW(port.BmsGet(bms, id)) > 0 {
		return 1
	}
	return 0
}

